# ruff: noqa: E501
"""Build the continuous interactive article from committed Stage 1-8 evidence."""

from __future__ import annotations

import hashlib
import html
import json
import math
import re
from pathlib import Path
from typing import Any, cast

from markdown_it import MarkdownIt

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "blog/article.md"
OUTPUT = ROOT / "blog/how-text-watermarks-hide-in-plain-sight.html"


def load(path: str) -> dict[str, Any]:
    return cast(dict[str, Any], json.loads((ROOT / path).read_text()))


def compact(value: object) -> str:
    return json.dumps(value, allow_nan=False, separators=(",", ":")).replace("</", "<\\/")


def build_toy_sentence_fixture() -> dict[str, Any]:
    """Build the declared Jack sentence fixture from the Stage 2 teaching contract."""

    vocabulary = (
        "Early",
        "one",
        "morning",
        "Jack",
        "went",
        "up",
        "the",
        "hill",
        "walked",
        "ran",
        "road",
        "path",
        "stairs",
        "and",
        "saw",
        "snow",
        "down",
        "home",
        ".",
        "trail",
    )
    lesson_key = "stage-02-public-demo-key-v1"
    comparison_key = "wrong-public-key"
    contexts = ((0, 1, 2, 3), (1, 2, 3, 4), (2, 3, 4, 5), (3, 4, 5, 6))
    targets = (4, 5, 6, 7)
    draws = (0.30, 0.35, 0.13, 0.06)
    high_scores = (
        {4: 1.7, 8: 1.4, 9: 1.9, 14: 1.2, 13: 0.5, 17: 0.2},
        {5: 1.7, 16: 1.9, 17: 1.5, 13: 0.8, 10: 0.4, 18: 0.1},
        {6: 2.2, 7: 1.3, 10: 1.1, 11: 0.9, 12: 0.7, 19: 0.5, 18: 0.2},
        {7: 2.5, 10: 1.8, 11: 1.6, 12: 1.4, 19: 1.2, 16: 0.4, 18: 0.2},
    )

    def rank(key: str, context: tuple[int, ...]) -> list[dict[str, Any]]:
        context_text = ",".join(str(token_id) for token_id in context)
        rows = []
        for token_id, word in enumerate(vocabulary):
            material = f"lab-02|v1|{key}|{context_text}|{token_id}"
            digest = hashlib.sha256(material.encode("ascii")).hexdigest()
            rows.append({"id": token_id, "word": word, "material": material, "hash": digest})
        rows.sort(key=lambda row: (row["hash"], row["id"]))
        for position, row in enumerate(rows, 1):
            row["rank"] = position
            row["green"] = position <= 5
        return sorted(rows, key=lambda row: row["id"])

    def probabilities(values: list[float]) -> list[float]:
        maximum = max(values)
        weights = [math.exp(value - maximum) for value in values]
        total = math.fsum(weights)
        return [weight / total for weight in weights]

    def sampled(probability: list[float], draw: float) -> int:
        cumulative = 0.0
        for token_id, value in enumerate(probability):
            cumulative += value
            if draw < cumulative:
                return token_id
        return len(probability) - 1

    steps = []
    for position, (context, target, draw, listed) in enumerate(
        zip(contexts, targets, draws, high_scores, strict=True), 1
    ):
        ranked = rank(lesson_key, context)
        raw = [listed.get(token_id, -2.2) for token_id in range(len(vocabulary))]
        adjusted = [
            value + (2.0 if ranked[token_id]["green"] else 0.0)
            for token_id, value in enumerate(raw)
        ]
        before = probabilities(raw)
        after = probabilities(adjusted)
        steps.append(
            {
                "position": position,
                "context": list(context),
                "context_words": [vocabulary[token_id] for token_id in context],
                "next_context_words": [vocabulary[token_id] for token_id in (*context[1:], target)],
                "ranked": ranked,
                "green_ids": [row["id"] for row in ranked if row["green"]],
                "green_words": [row["word"] for row in ranked if row["green"]],
                "raw_scores": raw,
                "adjusted_scores": adjusted,
                "before": before,
                "after": after,
                "draw": draw,
                "plain_id": sampled(before, draw),
                "marked_id": sampled(after, draw),
                "target_id": target,
                "target_word": vocabulary[target],
                "hit": ranked[target]["green"],
            }
        )
    comparison_steps = [rank(comparison_key, context) for context in contexts]
    return {
        "vocabulary": list(vocabulary),
        "lesson_key": lesson_key,
        "comparison_key": comparison_key,
        "steps": steps,
        "comparison_first": comparison_steps[0],
        "comparison_hits": [
            comparison_steps[index][target]["green"] for index, target in enumerate(targets)
        ],
    }


def markdown_renderer() -> MarkdownIt:
    return MarkdownIt("commonmark", {"html": True, "linkify": True}).enable("table")


def make_tables_responsive(rendered: str) -> str:
    """Wrap tables and label body cells for a no-scroll mobile layout."""

    def convert_table(match: re.Match[str]) -> str:
        table = match.group(0)
        headers = [
            re.sub(r"<[^>]+>", "", header).strip()
            for header in re.findall(r"<th(?:\s[^>]*)?>(.*?)</th>", table, flags=re.DOTALL)
        ]

        def convert_row(row_match: re.Match[str]) -> str:
            index = 0

            def label_cell(cell_match: re.Match[str]) -> str:
                nonlocal index
                label = headers[index] if index < len(headers) else f"Column {index + 1}"
                index += 1
                attributes = cell_match.group(1) or ""
                return f'<td data-label="{html.escape(label, quote=True)}"{attributes}>'

            return re.sub(r"<td(\s[^>]*)?>", label_cell, row_match.group(0))

        table = re.sub(r"<tr>.*?</tr>", convert_row, table, flags=re.DOTALL)
        return (
            '<div class="table-wrap" role="region" '
            'aria-label="Data table" tabindex="0">'
            f"{table}</div>"
        )

    return re.sub(r"<table>.*?</table>", convert_table, rendered, flags=re.DOTALL)


def render_markdown(source: str) -> str:
    definitions: list[tuple[str, str]] = []
    body: list[str] = []
    for line in source.splitlines():
        match = re.match(r"^\[\^([^]]+)\]:\s*(.+)$", line)
        if match:
            definitions.append((match.group(1), match.group(2)))
        else:
            body.append(line)
    numbers = {key: index for index, (key, _) in enumerate(definitions, 1)}
    joined = "\n".join(body)
    for key, number in numbers.items():
        joined = joined.replace(
            f"[^{key}]",
            f'<sup class="ref"><a href="#fn-{key}" aria-label="Source {number}">{number}</a></sup>',
        )
    renderer = markdown_renderer()
    rendered = make_tables_responsive(renderer.render(joined))
    notes = []
    for key, value in definitions:
        note = renderer.renderInline(value)
        notes.append(f'<li id="fn-{html.escape(key)}">{note}</li>')
    return rendered + '<ol class="footnotes">' + "".join(notes) + "</ol>"


